// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class PackedQueryFamilyIdentityTest {

	private static final SimpleValueFactory VALUES = SimpleValueFactory.getInstance();

	@Test
	void sameRdfShapeSharesFamilyWhileVectorsRemainInvocationLocal() {
		Value firstValue = VALUES.createIRI("urn:first");
		Value secondValue = VALUES.createIRI("urn:second");
		PackedQueryFamilyIdentity first = family(pattern(firstValue));
		PackedQueryFamilyIdentity second = family(pattern(secondValue));

		assertTrue(first.matches(second));
		assertEquals(first.parameterSchema(), second.parameterSchema());
		assertEquals(firstValue, first.parameterVector().value(0));
		assertEquals(secondValue, second.parameterVector().value(0));
		assertNotEquals(first.parameterVector().value(0), second.parameterVector().value(0));

		PackedQueryFamilyIdentity detached = first.detached();
		assertTrue(detached.matches(second));
		assertThrows(IllegalStateException.class, detached::parameterVector,
				"published family authentication must not retain invocation values");
		assertThrows(IllegalStateException.class, detached::concreteQuery,
				"published family authentication must not retain a concrete invocation query");
	}

	@Test
	void literalDatatypeAndLanguageRemainPartOfParameterSchema() {
		PackedQueryFamilyIdentity firstInteger = family(pattern(VALUES.createLiteral(1)));
		PackedQueryFamilyIdentity secondInteger = family(pattern(VALUES.createLiteral(2)));
		PackedQueryFamilyIdentity stringLiteral = family(pattern(VALUES.createLiteral("1")));
		PackedQueryFamilyIdentity englishLiteral = family(pattern(VALUES.createLiteral("one", "en")));
		PackedQueryFamilyIdentity frenchLiteral = family(pattern(VALUES.createLiteral("un", "fr")));

		assertTrue(firstInteger.matches(secondInteger));
		assertFalse(firstInteger.matches(stringLiteral));
		assertFalse(englishLiteral.matches(frenchLiteral));
	}

	@Test
	void repeatedAndIndependentConstantSlotsHaveOneStableFamilyShape() {
		TupleExpr repeated = new Join(pattern(VALUES.createIRI("urn:shared")),
				pattern(VALUES.createIRI("urn:shared")));
		TupleExpr independent = new Join(pattern(VALUES.createIRI("urn:left")),
				pattern(VALUES.createIRI("urn:right")));

		PackedQueryFamilyIdentity repeatedIdentity = family(repeated);
		PackedQueryFamilyIdentity independentIdentity = family(independent);

		assertTrue(repeatedIdentity.matches(independentIdentity));
		assertEquals(2, repeatedIdentity.parameterSchema().size());
		assertEquals(2, independentIdentity.parameterSchema().size());
		assertEquals(repeatedIdentity.parameterVector().value(0), repeatedIdentity.parameterVector().value(1));
		assertNotEquals(independentIdentity.parameterVector().value(0), independentIdentity.parameterVector().value(1));
	}

	private static PackedQueryFamilyIdentity family(TupleExpr source) {
		PackedQueryFamilyIdentity identity = PackedQueryFamilyIdentity.create(source, null);
		if (identity == null) {
			throw new AssertionError("test fixture must support a packed parameterized family");
		}
		return identity;
	}

	private static StatementPattern pattern(Value subject) {
		return new StatementPattern(Var.of("subject", subject), Var.of("predicate"), Var.of("object"));
	}
}
